uic:spaceOverviewPage.uic:css:
:uic-scope {
  --myne-slot-page-header-gap: 0.5rem;
  --myne-command-center-rail: 18rem;
  --myne-command-center-main: minmax(24rem, 1fr);
  background: linear-gradient(135deg, color-mix(in oklab, var(--myne-color-background) 88%, var(--myne-color-accent)), var(--myne-color-background));
  border: 1px solid color-mix(in oklab, var(--myne-color-border) 78%, var(--myne-color-accent));
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
  box-shadow: var(--myne-shadow-panel);
}
:uic-region(activeRail) {
  background: linear-gradient(180deg, color-mix(in oklab, var(--myne-color-panel) 78%, var(--myne-color-accent)), var(--myne-color-panel));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
  box-shadow: var(--myne-shadow-panel);
}
:uic-region(mainQueue) {
  background: color-mix(in oklab, var(--myne-color-panel) 92%, var(--myne-color-accent));
  border: 1px solid color-mix(in oklab, var(--myne-color-border) 72%, var(--myne-color-accent));
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
  box-shadow: var(--myne-shadow-panel);
}
:uic-region(memoryRail) {
  background: linear-gradient(180deg, color-mix(in oklab, var(--myne-color-panel) 84%, var(--myne-color-warning)), var(--myne-color-panel));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
}
:uic-slot(workspaceList) {
  background: color-mix(in oklab, var(--myne-color-panel) 86%, var(--myne-color-accent));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
}
:uic-slot(runningDevServers) {
  background: color-mix(in oklab, var(--myne-color-panel) 82%, var(--myne-color-success));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-md);
  padding: var(--myne-spacing-sm);
}
:uic-slot(recentSessions) {
  background: color-mix(in oklab, var(--myne-color-panel) 90%, var(--myne-color-accent));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-md);
  padding: var(--myne-spacing-sm);
}
:uic-slot(starredCraft) {
  background: color-mix(in oklab, var(--myne-color-panel) 84%, var(--myne-color-warning));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-md);
  padding: var(--myne-spacing-sm);
}
:uic-slot(recentlyVisitedCraft) {
  background: color-mix(in oklab, var(--myne-color-panel) 88%, var(--myne-color-accent));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-md);
  padding: var(--myne-spacing-sm);
}
:uic-slot(recentlyCreatedCraft) {
  background: color-mix(in oklab, var(--myne-color-panel) 88%, var(--myne-color-success));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-md);
  padding: var(--myne-spacing-sm);
}
